// validateVersionUpgrade is the shared safety gate for the dedicated GraphQL/
// MCP verb and REST's partial PATCH. Major versions are upward-only. A plan
// whose durability contract includes backups must have a completed physical
// backup before the offline pg_upgrade begins; checking BackupsEnabled alone is
// insufficient because the first ScheduledBackup may still be pending.
func (s *Service) validateVersionUpgrade(ctx context.Context, d *appv1alpha1.Database, target string, patchedPlan *string) error {
	if !postgresVersionKnown(target) {
		return unknownPostgresVersionError(target)
	}
	if d.Status.Phase == appv1alpha1.DBPhaseUpgrading {
		return core.NewConflictError(
			"POSTGRES_UPGRADE_IN_PROGRESS",
			"a PostgreSQL major-version upgrade is already in progress",
			map[string]any{"targetVersion": d.Spec.Version},
		)
	}
	current := d.Status.CurrentVersion
	currentMajor, currentErr := strconv.Atoi(current)
	targetMajor, targetErr := strconv.Atoi(target)
	if currentErr != nil || current == "" {
		return core.NewConflictError(
			"POSTGRES_VERSION_NOT_OBSERVED",
			"the running PostgreSQL version has not been observed yet; wait for the database to become available",
			map[string]any{"targetVersion": target},
		)
	}
	if targetErr != nil || targetMajor <= currentMajor {
		return core.NewBadRequestError(
			"POSTGRES_VERSION_NOT_NEWER",
			fmt.Sprintf("PostgreSQL version upgrades are upward-only: target %s must be newer than current version %s", target, current),
			map[string]any{"currentVersion": current, "targetVersion": target},
		)
	}
	if targetMajor < minPostgresUpgradeTarget {
		return core.NewBadRequestError(
			"POSTGRES_UPGRADE_TARGET_UNSUPPORTED",
			fmt.Sprintf("upgrading PostgreSQL %s to %s is not supported: major-version upgrades must target version %d or newer", current, target, minPostgresUpgradeTarget),
			map[string]any{"currentVersion": current, "targetVersion": target, "minimumTargetVersion": strconv.Itoa(minPostgresUpgradeTarget)},
		)
	}
	requiresBackup := planRequiresUpgradeBackup(d.Spec.Plan)
	if patchedPlan != nil {
		requiresBackup = requiresBackup || planRequiresUpgradeBackup(*patchedPlan)

func AddTool[In, Out any](s *mcp.Server, t *mcp.Tool, h mcp.ToolHandlerFor[In, Out]) {
	mcp.AddTool(s, t, func( //nolint:forbidigo // the seam itself: it wraps the handler, then delegates
		ctx context.Context, req *mcp.CallToolRequest, in In) (res *mcp.CallToolResult, out Out, err error) {

// Keep this catalog in sync with Database.spec.version's CRD enum and the
// backend's guarded major-upgrade catalog. Descending order makes the newest
// supported version the default upgrade target, matching Render's flow.
export const POSTGRES_VERSIONS = ["18", "17", "16", "15", "14", "13"] as const;

// CNPG's in-place major upgrade only targets 16 or newer; the backend refuses
// lower targets as POSTGRES_UPGRADE_TARGET_UNSUPPORTED (w4/308). Creation still
// offers the whole catalog.
const MIN_UPGRADE_TARGET = 16;

export function postgresUpgradeTargets(current: string | null): string[] {
  const major = Number(current);
  if (!Number.isInteger(major)) return [];
  return POSTGRES_VERSIONS.filter(
    (version) =>
      Number(version) > major && Number(version) >= MIN_UPGRADE_TARGET,
  );
}

func setSchema[T any](sfield *any, rfield **jsonschema.Resolved, cache *SchemaCache) (zero any, err error) {
	rt := reflect.TypeFor[T]()
	if rt.Kind() == reflect.Pointer {
		rt = rt.Elem()
		zero = reflect.Zero(rt).Interface()
	}

	var internalSchema *jsonschema.Schema

	if *sfield == nil {
		// No schema provided: check cache, or generate via reflection.
		if cache != nil {
			if schema, resolved, ok := cache.getByType(rt); ok {
				*sfield = schema
				*rfield = resolved
				return zero, nil
			}
		}

		internalSchema, err = jsonschema.ForType(rt, &jsonschema.ForOptions{})
		if err != nil {
			return zero, err
		}
		*sfield = internalSchema

		resolved, err := internalSchema.Resolve(&jsonschema.ResolveOptions{ValidateDefaults: true})
		if err != nil {
			return zero, err
		}

	return nil, err
}
